CREATE TABLE tickets(tenant text NOT NULL,id text NOT NULL,owner_id text NOT NULL,subject text NOT NULL,message text NOT NULL,status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','drafted','approved','sent','closed')),category text,draft text,version integer NOT NULL DEFAULT 1,sla_at timestamptz NOT NULL DEFAULT now()+interval '24 hours',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant,id));
CREATE TABLE ticket_audit(id bigserial PRIMARY KEY,tenant text NOT NULL,ticket_id text NOT NULL,actor text NOT NULL,action text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_replies(tenant text NOT NULL,ticket_id text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant,ticket_id),FOREIGN KEY(tenant,ticket_id) REFERENCES tickets(tenant,id));
